const http = require('http');
const crypto = require('crypto');
const { URL } = require('url');

// In-memory stores
const sessions = new Map();
const users = new Map();
const documents = new Map();
const auditLog = [];

// Initialize users
users.set(1, { id: 1, name: 'admin', role: 'admin', department: 'IT' });
users.set(2, { id: 2, name: 'alice', role: 'editor', department: 'Marketing' });
users.set(3, { id: 3, name: 'bob', role: 'viewer', department: 'Sales' });

// Initialize documents
documents.set('doc1', { id: 'doc1', title: 'Budget Report', owner: 1, department: 'IT', classification: 'confidential' });
documents.set('doc2', { id: 'doc2', title: 'Marketing Plan', owner: 2, department: 'Marketing', classification: 'internal' });
documents.set('doc3', { id: 'doc3', title: 'Public FAQ', owner: 3, department: 'Sales', classification: 'public' });

class RBACEngine {
  constructor() {
    this.policies = [
      { role: 'admin', resource: '*', actions: ['read', 'write', 'delete', 'share'] },
      { role: 'editor', resource: 'own_department', actions: ['read', 'write'] },
      { role: 'viewer', resource: 'own_department', actions: ['read'] }
    ];
  }

  checkAccess(user, document, action) {
    if (!user || !document) return false;

    const applicablePolicies = this.policies.filter(p => p.role === user.role);

    for (const policy of applicablePolicies) {
      if (!policy.actions.includes(action)) continue;

      if (policy.resource === '*') return true;
      if (policy.resource === 'own_department' && document.department === user.department) return true;
      if (policy.resource === 'public' && document.classification === 'public') return true;
    }

    // Public documents readable by all authenticated users
    if (action === 'read' && document.classification === 'public') return true;

    return false;
  }
}

const rbac = new RBACEngine();

class SessionManager {
  constructor() {
    this.tokenLength = 32;
    this.maxAge = 3600000; // 1 hour
  }

  createSession(userId) {
    const token = crypto.randomBytes(this.tokenLength).toString('hex');
    const session = {
      token,
      userId: userId,
      createdAt: Date.now(),
      lastAccess: Date.now(),
      metadata: {}
    };
    sessions.set(token, session);
    return token;
  }

  validateSession(token) {
    if (!token || typeof token !== 'string') return null;
    if (!/^[a-f0-9]{64}$/.test(token)) return null;

    const session = sessions.get(token);
    if (!session) return null;

    if (Date.now() - session.createdAt > this.maxAge) {
      sessions.delete(token);
      return null;
    }

    session.lastAccess = Date.now();
    return session;
  }

  // Delegation: allow a session to act on behalf of another user
  delegateSession(session, targetUserId) {
    if (typeof targetUserId !== 'number' || !Number.isInteger(targetUserId)) {
      throw new Error('Invalid target user ID');
    }
    session.metadata.delegatedFrom = session.userId;
    session.metadata.actingAs = targetUserId;
    return session;
  }
}

const sessionMgr = new SessionManager();

function getEffectiveUser(session) {
  // If session has delegation, return the delegated user
  if (session.metadata && session.metadata.actingAs !== undefined) {
    const actingAsId = session.metadata.actingAs;
    // Security check: verify the original user has permission to delegate
    const originalUser = users.get(session.userId);
    if (originalUser && originalUser.role === 'admin') {
      return users.get(actingAsId);
    }
    // Non-admin delegation: only allow if same user
    // Use strict comparison to verify identity
    if (session.userId === actingAsId) {
      return users.get(session.userId);
    }
    return null;
  }
  return users.get(session.userId);
}

function parseBody(req) {
  return new Promise((resolve, reject) => {
    const chunks = [];
    let size = 0;
    req.on('data', chunk => {
      size += chunk.length;
      if (size > 10240) {
        reject(new Error('Body too large'));
        req.destroy();
        return;
      }
      chunks.push(chunk);
    });
    req.on('end', () => {
      try {
        const body = Buffer.concat(chunks).toString('utf8');
        resolve(JSON.parse(body));
      } catch (e) {
        reject(new Error('Invalid JSON'));
      }
    });
    req.on('error', reject);
  });
}

function authenticate(req) {
  const authHeader = req.headers['authorization'];
  if (!authHeader || !authHeader.startsWith('Bearer ')) return null;
  const token = authHeader.slice(7);
  return sessionMgr.validateSession(token);
}

function logAccess(userId, action, resource, allowed) {
  auditLog.push({
    timestamp: Date.now(),
    userId,
    action,
    resource,
    allowed,
    id: crypto.randomBytes(8).toString('hex')
  });
}

async function handleLogin(req, res) {
  try {
    const body = await parseBody(req);
    if (!body || typeof body.userId !== 'number') {
      res.writeHead(400, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: 'Invalid request' }));
      return;
    }

    const user = users.get(body.userId);
    if (!user) {
      res.writeHead(401, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: 'User not found' }));
      return;
    }

    const token = sessionMgr.createSession(user.id);
    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ token, user: { id: user.id, name: user.name, role: user.role } }));
  } catch (e) {
    res.writeHead(400, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: e.message }));
  }
}

async function handleDelegate(req, res) {
  const session = authenticate(req);
  if (!session) {
    res.writeHead(401, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: 'Unauthorized' }));
    return;
  }

  try {
    const body = await parseBody(req);
    if (!body || body.targetUserId === undefined) {
      res.writeHead(400, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: 'Missing targetUserId' }));
      return;
    }

    sessionMgr.delegateSession(session, body.targetUserId);
    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ success: true, actingAs: body.targetUserId }));
  } catch (e) {
    res.writeHead(400, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: e.message }));
  }
}

async function handleDocument(req, res, docId, action) {
  const session = authenticate(req);
  if (!session) {
    res.writeHead(401, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: 'Unauthorized' }));
    return;
  }

  const user = getEffectiveUser(session);
  if (!user) {
    res.writeHead(403, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: 'Access denied - invalid delegation' }));
    return;
  }

  const doc = documents.get(docId);
  if (!doc) {
    res.writeHead(404, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: 'Document not found' }));
    return;
  }

  const allowed = rbac.checkAccess(user, doc, action);
  logAccess(user.id, action, docId, allowed);

  if (!allowed) {
    res.writeHead(403, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: 'Access denied by policy' }));
    return;
  }

  if (action === 'read') {
    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ document: doc }));
  } else if (action === 'delete') {
    documents.delete(docId);
    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ success: true }));
  } else {
    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ success: true, action }));
  }
}

const server = http.createServer(async (req, res) => {
  try {
    const parsedUrl = new URL(req.url, `http://${req.headers.host || 'localhost'}`);
    const pathname = parsedUrl.pathname;

    if (req.method === 'POST' && pathname === '/login') {
      await handleLogin(req, res);
    } else if (req.method === 'POST' && pathname === '/delegate') {
      await handleDelegate(req, res);
    } else if (req.method === 'GET' && pathname.startsWith('/documents/')) {
      const docId = pathname.split('/')[2];
      if (docId && /^[a-zA-Z0-9_-]+$/.test(docId)) {
        await handleDocument(req, res, docId, 'read');
      } else {
        res.writeHead(400, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: 'Invalid document ID' }));
      }
    } else if (req.method === 'DELETE' && pathname.startsWith('/documents/')) {
      const docId = pathname.split('/')[2];
      if (docId && /^[a-zA-Z0-9_-]+$/.test(docId)) {
        await handleDocument(req, res, docId, 'delete');
      } else {
        res.writeHead(400, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: 'Invalid document ID' }));
      }
    } else if (req.method === 'GET' && pathname === '/audit') {
      const session = authenticate(req);
      if (!session) {
        res.writeHead(401, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: 'Unauthorized' }));
        return;
      }
      const user = getEffectiveUser(session);
      if (!user || user.role !== 'admin') {
        res.writeHead(403, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: 'Admin only' }));
        return;
      }
      res.writeHead(200, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ logs: auditLog.slice(-100) }));
    } else {
      res.writeHead(404, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: 'Not found' }));
    }
  } catch (e) {
    res.writeHead(500, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: 'Internal error' }));
  }
});

server.listen(3000);
module.exports = { server, sessionMgr, rbac, getEffectiveUser };
